/**
 * Gift Flower - Clean Version (No API)
 * Chỉ dùng defaults + URL params (?c= / ?b= / query string)
 * Original: https://giftflower3000.netlify.app/main.min.js
 */

// ==================== DATA ENCODING ====================

function encodeData(data) {
  try {
    const json = JSON.stringify(data);
    const compressed = pako.deflate(json);
    let binary = "";
    for (let i = 0; i < compressed.length; i++) {
      binary += String.fromCharCode(compressed[i]);
    }
    return btoa(binary)
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=/g, "");
  } catch (err) {
    console.error("Lỗi khi mã hóa dữ liệu:", err);
    return null;
  }
}

function decodeData(encoded) {
  try {
    let base64 = encoded.replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4) {
      base64 += "=";
    }
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    const json = pako.inflate(bytes, { to: "string" });
    return JSON.parse(json);
  } catch (err) {
    console.error("Lỗi khi giải mã dữ liệu:", err);
    return null;
  }
}

// ==================== SETTINGS ====================

let flyingImageUrls = [];
let flyingImagesEnabled = true;
let flyingImagesShown = false;
let mainStarted = false;
let headerTypingActive = false;
let isPlaying = false;
let musicInitialized = false;
let userInteractionListener = null;
let popupJustClosed = false;
let typingTimeout = null;
let typingIntervals = [];

function getUrlParameter(key) {
  const params = new URLSearchParams(window.location.search);

  // 1. From ?b= (simple base64)
  const bParam = params.get("b");
  if (bParam) {
    try {
      const decoded = JSON.parse(
        decodeURIComponent(escape(atob(bParam.replace(/-/g, "+").replace(/_/g, "/"))))
      );
      if (key === "messages" && decoded.t) {
        return Array.isArray(decoded.t)
          ? decoded.t
          : decoded.t.split(",").map((s) => s.trim());
      }
      if (key === "music" && decoded.m) return decoded.m;
      if (key === "image" && decoded.i) return decoded.i;
      if (key === "title" && decoded.title) return decoded.title;
    } catch (err) {
      console.error("Error decoding ?b= parameter:", err);
    }
  }

  // 2. From ?c= (pako + base64url) — cách chính để truyền data (giống API)
  const cParam = params.get("c");
  if (cParam) {
    const data = decodeData(cParam);
    if (data) {
      if (key === "title" && data.title) return data.title;
      if (key === "subtitle" && data.subtitle) return data.subtitle;
      if (key === "instructionText" && data.instructionText) return data.instructionText;
      if (key === "modalTitle" && data.modalTitle) return data.modalTitle;
      if (key === "modalContent" && data.modalContent) return data.modalContent;
      if (key === "image" && data.image) return data.image;
      if (key === "music" && data.music) return data.music;
      if (key === "messages" && data.messages) return data.messages;
    }
  }

  // 3. Direct query param
  return params.get(key) || null;
}

// ==================== APP FLOW ====================

async function enterMain() {
  if (mainStarted) return;
  mainStarted = true;

  const intro = document.getElementById("introScreen");
  const main = document.getElementById("mainContent");

  intro.classList.add("fade-out");
  main.classList.remove("hidden");

  setTimeout(() => intro.remove(), 900);
  startMainApp();
}

function startMainApp() {
  document.body.classList.remove("container");
  initializeContent();

  createStarryNight();
  createFallingPetals();

  const musicToggle = getMusicToggle();
  if (musicToggle) {
    musicToggle.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      toggleMusic();
    });
  }

  setupFlowerClickHandlers();

  setTimeout(createSparkles, 6000);

  setTimeout(() => {
    if (flyingImagesShown) return;
    const instruction = document.querySelector(".instruction");
    if (instruction) {
      instruction.style.opacity = "0";
      instruction.style.display = "block";
      setTimeout(() => {
        instruction.style.transition = "opacity 1s ease-in";
        instruction.style.opacity = "1";
      }, 100);
    }
  }, 5000);

  setTimeout(playMusic, 300);
}

window.onload = () => {
  initializeContent();
};

// ==================== CONTENT ====================

function initializeContent() {
  console.log("🎨 Initializing content from defaults / URL params...");

  const defaults = {
    title: "Gửi người anh yêu 💖",
    messages: [
      "💖 Gửi em — tình yêu của anh",
      "Yêu em — hôm nay, ngày mai và mãi mãi 💕✨",
      "Cảm ơn em vì đã đến bên đời anh 🌹"
    ],
    instructionText: "Chạm vào hoa để nhận lời yêu",
    modalTitle: "Gửi Người Anh Yêu 💖",
    modalContent:
      "💘 Em à, mỗi ngày bên em đều là một ngày đặc biệt của anh. Cảm ơn em vì đã yêu anh, vì đã luôn ở đây cùng anh đi qua bao buồn vui. Anh hứa sẽ yêu thương, trân trọng và che chở em suốt cuộc đời này. Mãi yêu em 💕",
    music:
      "https://cdn.shopify.com/s/files/1/0757/9700/4572/files/tiktok-music-1780247017983-dx1cxk.mp3?v=1780247021",
    // Ảnh bay (flying images) — thay bằng link ảnh của bạn
    images: [
      //"https://i.pinimg.com/736x/a0/1b/16/a01b1678b0475f076dc537b1fe803677.jpg"
    ]
  };

  // Messages
  let messages = defaults.messages;
  const messagesParam = getUrlParameter("messages");
  if (messagesParam) {
    messages = Array.isArray(messagesParam)
      ? messagesParam
      : messagesParam.split(",").map((s) => s.trim());
  }
  messages = messages.filter((m) => m && m.trim() !== "");

  // Title
  const titleEl = document.querySelector(".teachers-day-title");
  const title = getUrlParameter("title") || defaults.title;
  if (titleEl) titleEl.textContent = title;

  // Typing messages
  const dateEl = document.querySelector(".teachers-day-date");
  if (dateEl) {
    dateEl.style.display = "block";
    startTypingMessages(dateEl, messages);
  }

  // Instruction text
  const instructionTextEl = document.querySelector(".instruction-text");
  const instructionText = getUrlParameter("instructionText") || defaults.instructionText;
  if (instructionTextEl) {
    instructionTextEl.innerHTML =
      instructionText + ' <span class="instruction-icon">👆</span>';
  }

  // Modal / Popup content
  const popupTitle = document.querySelector(".popup-title");
  const popupMessage = document.querySelector(".popup-message");
  const modalTitle = getUrlParameter("modalTitle") || defaults.modalTitle;
  const modalContent = getUrlParameter("modalContent") || defaults.modalContent;

  if (popupTitle) popupTitle.innerHTML = modalTitle;
  if (popupMessage) popupMessage.innerHTML = modalContent.replace(/\n/g, "<br>");

  // ========== ẢNH ==========
  // Cách 1: hardcode trong defaults.images (dùng mặc định)
  // Cách 2: truyền qua URL param ?c= (encodeData) hoặc ?image=
  let imageParam = getUrlParameter("image");
  if (Array.isArray(imageParam) && imageParam.length > 0) {
    flyingImageUrls = imageParam.filter((url) => url && url.trim() !== "");
  } else if (imageParam && typeof imageParam === "string") {
    // Có thể là 1 link hoặc nhiều link cách nhau bởi dấu phẩy
    flyingImageUrls = imageParam.split(",").map((s) => s.trim()).filter(Boolean);
  } else {
    // Không có param → dùng defaults
    flyingImageUrls = defaults.images.slice();
  }

  const cardImageWrap = document.querySelector(".popup-card-image");
  const cardImage = document.querySelector(".popup-card-image img");

  // Luôn bật flying images nếu có ảnh
  flyingImagesEnabled = flyingImageUrls.length > 0;

  if (flyingImageUrls.length > 0) {
    if (cardImage) cardImage.src = flyingImageUrls[0];
    if (cardImageWrap) cardImageWrap.style.display = "block";
  } else {
    if (cardImageWrap) cardImageWrap.style.display = "none";
  }

  // Music
  const musicUrl = getUrlParameter("music") || defaults.music;
  const bgMusic = document.getElementById("bgMusic");

  console.log("🎵 Initializing music...");
  console.log("Music URL:", musicUrl);

  if (bgMusic && musicUrl) {
    bgMusic.src = musicUrl;
    bgMusic.volume = 0.5;
    bgMusic.loop = true;
    bgMusic.preload = "auto";
    bgMusic.load();
    console.log("✅ Music source set to:", musicUrl);
  } else {
    console.error("❌ bgMusic element not found!");
  }

  console.log("✅ Content initialization complete");
  console.log("📷 Flying images:", flyingImageUrls);
}

// ==================== TYPING EFFECT ====================

function startTypingMessages(element, messages) {
  if (headerTypingActive) return;
  headerTypingActive = true;

  let messageIndex = 0;
  let charIndex = 0;
  const typeSpeed = 80;
  const pauseDuration = 2500;
  let isPaused = false;
  let pauseStart = 0;

  function tick() {
    const now = Date.now();
    const currentMessage = messages[messageIndex];

    if (!isPaused) {
      if (!tick.lastType || now - tick.lastType > typeSpeed) {
        charIndex++;
        const cursor = Math.floor(now / 500) % 2 === 0 ? "|" : "";
        element.textContent = currentMessage.substring(0, charIndex) + cursor;
        tick.lastType = now;

        if (charIndex > currentMessage.length) {
          isPaused = true;
          pauseStart = now;
        }
      }
    } else {
      const cursor = Math.floor(now / 500) % 2 === 0 ? "|" : "";
      element.textContent = currentMessage + cursor;

      if (now - pauseStart > pauseDuration) {
        isPaused = false;
        charIndex = 0;
        messageIndex = (messageIndex + 1) % messages.length;
        element.textContent = "";
      }
    }

    requestAnimationFrame(tick);
  }

  tick();
}

// ==================== EFFECTS ====================

function createStarryNight() {
  const night = document.querySelector(".night");
  if (!night) {
    console.error("Night element not found");
    return;
  }

  const isMobile = window.innerWidth <= 600;
  const starCount = isMobile ? 80 : 200;

  for (let i = 0; i < starCount; i++) {
    const star = document.createElement("div");
    star.className = "star";

    const size = Math.random();
    if (size < 0.5) star.classList.add("small");
    else if (size < 0.8) star.classList.add("medium");
    else star.classList.add("large");

    star.style.left = Math.random() * 100 + "%";
    star.style.top = Math.random() * 100 + "%";
    star.style.animationDuration = 2 + Math.random() * 3 + "s";
    star.style.animationDelay = Math.random() * 3 + "s";

    night.appendChild(star);
  }
}

function createFallingPetals() {
  const petals = ["🌷", "🌸", "🌺", "💐"];
  const isMobile = window.innerWidth <= 600;
  const count = isMobile ? 8 : 15;
  const night = document.querySelector(".night");
  if (!night) return;

  for (let i = 0; i < count; i++) {
    const petal = document.createElement("div");
    petal.className = "petal";
    petal.textContent = petals[Math.floor(Math.random() * petals.length)];
    petal.style.left = Math.random() * 100 + "%";
    petal.style.fontSize = 14 + Math.random() * 16 + "px";
    petal.style.animationDuration = 6 + Math.random() * 8 + "s";
    petal.style.animationDelay = Math.random() * 10 + "s";
    night.appendChild(petal);
  }
}

function createSparkles() {
  const isMobile = window.innerWidth <= 600;
  const count = isMobile ? 8 : 15;
  const flowers = document.querySelector(".flowers");
  if (!flowers) return;

  const hearts = ["❤️", "💕", "💗", "💖"];

  for (let i = 0; i < count; i++) {
    setTimeout(() => {
      const sparkle = document.createElement("div");
      sparkle.textContent = hearts[Math.floor(Math.random() * hearts.length)];

      const drift = -30 + Math.random() * 60;
      const duration = 2 + Math.random() * 2;

      sparkle.style.cssText = `
        position: absolute;
        font-size: ${12 + Math.random() * 14}px;
        pointer-events: none;
        left: ${30 + Math.random() * 40}%;
        bottom: 40%;
        z-index: 200;
        animation: heart-float ${duration}s ease-out forwards;
        --drift: ${drift}px;
      `;

      flowers.appendChild(sparkle);
      setTimeout(() => sparkle.remove(), 4000);
    }, i * 200);
  }
}

// ==================== MUSIC ====================

function getBgMusic() {
  return document.getElementById("bgMusic");
}

function getMusicToggle() {
  return document.getElementById("musicToggle");
}

function getMusicIcon() {
  return document.getElementById("musicIcon");
}

function playMusic() {
  const audio = getBgMusic();
  if (!audio) {
    console.error("bgMusic element not found in playMusic()");
    return;
  }

  console.log("playMusic() called, readyState:", audio.readyState, "src:", audio.src);

  if (!audio.src) {
    console.log("No music src found");
    return;
  }

  if (audio.readyState >= 2) {
    tryPlayMusic();
  } else {
    console.log("Waiting for audio to load...");
    audio.addEventListener("canplay", tryPlayMusic, { once: true });
    audio.addEventListener(
      "error",
      (e) => console.error("Audio loading error:", e, audio.error),
      { once: true }
    );
  }
}

function tryPlayMusic() {
  const audio = getBgMusic();
  const toggle = getMusicToggle();
  const icon = getMusicIcon();

  if (!audio || !audio.src) {
    console.error("Music element or source not found");
    return;
  }

  console.log("Attempting to play music:", audio.src);
  audio.volume = 0.5;

  const promise = audio.play();
  if (promise !== undefined) {
    promise
      .then(() => {
        console.log("Music playing successfully");
        isPlaying = true;
        musicInitialized = true;
        if (toggle) toggle.classList.add("playing");
        if (icon) {
          icon.classList.add("playing");
          icon.classList.remove("muted");
        }
      })
      .catch((err) => {
        console.log("Autoplay prevented, waiting for user interaction:", err);
        isPlaying = false;
        if (toggle) toggle.classList.remove("playing");
        if (icon) {
          icon.classList.remove("playing");
          icon.classList.add("muted");
        }

        if (userInteractionListener) {
          document.removeEventListener("click", userInteractionListener);
        }

        userInteractionListener = function () {
          console.log("User clicked, trying to play music");
          const a = getBgMusic();
          if (a) {
            a.play()
              .then(() => {
                console.log("Music started after user interaction");
                isPlaying = true;
                musicInitialized = true;
                const t = getMusicToggle();
                const i = getMusicIcon();
                if (t) t.classList.add("playing");
                if (i) {
                  i.classList.add("playing");
                  i.classList.remove("muted");
                }
              })
              .catch((e) => console.error("Failed to play music after user interaction:", e));
          }
          userInteractionListener = null;
        };

        document.addEventListener("click", userInteractionListener, { once: true });
      });
  }
}

function toggleMusic() {
  const audio = getBgMusic();
  const toggle = getMusicToggle();
  const icon = getMusicIcon();

  if (!audio) {
    console.error("Music element not found");
    return;
  }

  if (isPlaying) {
    console.log("Pausing music");
    audio.pause();
    isPlaying = false;
    if (toggle) toggle.classList.remove("playing");
    if (icon) {
      icon.classList.remove("playing");
      icon.classList.add("muted");
    }
  } else {
    console.log("Starting music...");

    const doPlay = () => {
      const promise = audio.play();
      if (promise !== undefined) {
        promise
          .then(() => {
            console.log("✅ Music started successfully!");
            isPlaying = true;
            musicInitialized = true;
            if (toggle) toggle.classList.add("playing");
            if (icon) {
              icon.classList.add("playing");
              icon.classList.remove("muted");
            }
          })
          .catch((err) => {
            console.error("❌ Failed to play music:", err);
            isPlaying = false;
            if (toggle) toggle.classList.remove("playing");
            if (icon) {
              icon.classList.remove("playing");
              icon.classList.add("muted");
            }
          });
      }
    };

    if (audio.readyState < 2) {
      audio.addEventListener("canplay", doPlay, { once: true });
    } else {
      doPlay();
    }
  }
}

// ==================== POPUP ====================

function openPopup() {
  const popup = document.getElementById("flowerPopup");
  const messageEl = document.querySelector(".popup-message");
  const titleEl = document.querySelector(".popup-title");
  const instruction = document.querySelector(".instruction");

  if (instruction) instruction.style.display = "none";

  // Try to start music if not playing
  if (!musicInitialized || !isPlaying) {
    const audio = getBgMusic();
    if (audio && audio.src) {
      audio
        .play()
        .then(() => {
          isPlaying = true;
          musicInitialized = true;
          const t = getMusicToggle();
          const i = getMusicIcon();
          if (t) t.classList.add("playing");
          if (i) {
            i.classList.add("playing");
            i.classList.remove("muted");
          }
        })
        .catch(() => {});
    }
  }

  popup.classList.add("active");
  document.body.style.overflow = "hidden";
  createSparkles();

  // Clear previous typing
  if (typingTimeout) {
    clearTimeout(typingTimeout);
    typingTimeout = null;
  }
  typingIntervals.forEach(clearTimeout);
  typingIntervals = [];

  if (messageEl) {
    if (!messageEl.getAttribute("data-original-text")) {
      messageEl.setAttribute("data-original-text", messageEl.textContent.trim());
    }

    const originalText = messageEl.getAttribute("data-original-text");
    messageEl.classList.remove("typing-done");

    if (titleEl) {
      titleEl.style.animation = "none";
      titleEl.offsetWidth; // force reflow
      titleEl.style.animation = "";
    }

    messageEl.textContent = "";
    messageEl.style.opacity = "0";

    setTimeout(() => {
      messageEl.style.opacity = "1";
      let i = 0;
      const speed = 30;

      function typeChar() {
        if (i < originalText.length) {
          messageEl.textContent += originalText.charAt(i);
          i++;
          const t = setTimeout(typeChar, speed);
          typingIntervals.push(t);
        } else {
          messageEl.classList.add("typing-done");
        }
      }

      typingTimeout = setTimeout(typeChar, 800);
    }, 50);
  }
}

function closePopup() {
  const popup = document.getElementById("flowerPopup");
  const messageEl = document.querySelector(".popup-message");

  if (typingTimeout) {
    clearTimeout(typingTimeout);
    typingTimeout = null;
  }
  typingIntervals.forEach(clearTimeout);
  typingIntervals = [];

  if (messageEl) {
    messageEl.classList.remove("typing-done");
    const original = messageEl.getAttribute("data-original-text");
    if (original) messageEl.textContent = original;
    messageEl.style.opacity = "0";
  }

  popup.classList.remove("active");
  document.body.style.overflow = "auto";

  // Show flying images after first close
  if (!flyingImagesShown && flyingImagesEnabled) {
    flyingImagesShown = true;
    hideFlowersAndShowImages();
  }

  popupJustClosed = true;
  setTimeout(() => {
    popupJustClosed = false;
  }, 300);
}

function hideFlowersAndShowImages() {
  const flowers = document.querySelector(".flowers");
  if (flowers) flowers.classList.add("flowers-hidden");

  const instruction = document.querySelector(".instruction");
  if (instruction) instruction.style.display = "none";

  const container = document.getElementById("flyingImages");
  if (!container) return;

  // Dùng flyingImageUrls đã set trong initializeContent (defaults hoặc từ URL)
  const images = flyingImageUrls.length > 0 ? flyingImageUrls : [];

  function renderImages() {
    container.innerHTML = "";
    const count = images.length;
    if (count === 0) return;

    const positions = [];
    for (let i = 0; i < count; i++) {
      positions.push(10 + (80 / (count - 1 || 1)) * i);
    }

    images.forEach((src, index) => {
      const img = document.createElement("img");
      img.src = src;
      img.className = "flying-img";
      img.alt = "Photo " + (index + 1);
      img.style.left = positions[index] + "%";
      img.style.transform = "translateX(-50%)";

      const delay = 0.3 + index * 0.5;
      const duration = 5 + Math.random() * 2;
      const driftX = -30 + Math.random() * 60;
      const rotate = -15 + Math.random() * 30;

      img.style.setProperty("--fly-delay", delay + "s");
      img.style.setProperty("--fly-duration", duration + "s");
      img.style.setProperty("--drift-x", driftX + "px");
      img.style.setProperty("--rotate", rotate + "deg");

      container.appendChild(img);
    });
  }

  renderImages();
  setInterval(renderImages, 8000);
}

// ==================== EVENT HANDLERS ====================

function setupFlowerClickHandlers() {
  const mainContent = document.getElementById("mainContent");
  if (!mainContent) return;

  mainContent.addEventListener("click", (e) => {
    if (popupJustClosed) return;
    if (e.target.closest("#musicToggle")) return;
    if (e.target.closest("#flowerPopup")) return;

    const popup = document.getElementById("flowerPopup");
    if (popup && popup.classList.contains("active")) return;

    openPopup();
  });
}

// Close button
(function setupCloseButton() {
  const btn = document.getElementById("popupCloseBtn");
  if (!btn) return;

  btn.addEventListener(
    "touchend",
    (e) => {
      e.preventDefault();
      e.stopPropagation();
      closePopup();
    },
    { passive: false }
  );

  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    closePopup();
  });
})();

// Click outside popup to close
window.addEventListener("click", (e) => {
  const popup = document.getElementById("flowerPopup");
  if (e.target === popup) closePopup();
});

// Modal helpers (legacy)
function openModal() {
  const modal = document.getElementById("wishModal");
  if (modal) {
    modal.classList.add("show");
    document.body.style.overflow = "hidden";
  }
}

function closeModal() {
  const modal = document.getElementById("wishModal");
  if (modal) {
    modal.classList.remove("show");
    document.body.style.overflow = "auto";
  }
}

window.onclick = function (e) {
  const modal = document.getElementById("wishModal");
  if (e.target === modal) closeModal();
};

// Inject sparkle animation
const style = document.createElement("style");
style.textContent = `
  @keyframes sparkle-burst {
    0% {
      transform: translate(-50%, -50%) rotate(var(--angle)) translateX(0) scale(1);
      opacity: 1;
    }
    100% {
      transform: translate(-50%, -50%) rotate(var(--angle)) translateX(150px) scale(0);
      opacity: 0;
    }
  }
`;
document.head.appendChild(style);
